/* Clustering de volatilité & enveloppe EWMA — série déterministe */
(function () {
  var svg = document.getElementById("vol-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }

  // Série de rendements déterministe présentant du clustering (seed fixe)
  var N = 130, seed = 20260905;
  function rnd(){ seed = (seed*1103515245 + 12345) & 0x7fffffff; return seed/0x7fffffff; }
  function gauss(){ var u=0,w=0; while(u===0)u=rnd(); while(w===0)w=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*w); }
  var rets=[];
  for (var i=0;i<N;i++){
    var scale;
    if (i<38) scale=0.007;          // calme
    else if (i<66) scale=0.028;     // régime turbulent 1
    else if (i<98) scale=0.010;     // accalmie
    else scale=0.023;               // régime turbulent 2
    rets.push(gauss()*scale);
  }

  var KZ = [1.2816,1.6449,1.9600,2.3263];
  var KL = ["90%","95%","97.5%","99%"];

  function draw(){
    var lam=v("vol-lam"); setT("vol-lam-o", lam.toFixed(2));
    var ki=Math.round(v("vol-k")), k=KZ[ki]; setT("vol-k-o", KL[ki]);

    // EWMA : amorçage par la variance d'échantillon des 20 premiers rendements
    var s0=0; for(var a=0;a<20;a++) s0+=rets[a]*rets[a]; s0/=20;
    var sig2=s0, sigs=[];
    for (var t=0;t<N;t++){ sig2 = lam*sig2 + (1-lam)*rets[t]*rets[t]; sigs.push(Math.sqrt(sig2)); }
    var last=sigs[N-1];
    var half=Math.log(0.5)/Math.log(lam);
    var exc=0; for (var e2=0;e2<N;e2++){ if (Math.abs(rets[e2])>k*sigs[e2]) exc++; }
    setT("vol-daily",(last*100).toFixed(2)+"%");
    setT("vol-ann",(last*Math.sqrt(252)*100).toFixed(1)+"%");
    setT("vol-half",half.toFixed(1));
    setT("vol-exc",exc+"/"+N);

    var W=520,H=260,L=34,R=12,T=12,B=26,pw=W-L-R,ph=H-T-B;
    var ymax=0; for (var m=0;m<N;m++){ ymax=Math.max(ymax, Math.abs(rets[m]), k*sigs[m]); }
    ymax*=1.08;
    function px(idx){ return L + idx/(N-1)*pw; }
    function py(y){ return T + (1-(y+ymax)/(2*ymax))*ph; }

    var g="";
    // Enveloppe ±k·σ_t (bande remplie)
    var up="M "+px(0).toFixed(1)+","+py(k*sigs[0]).toFixed(1);
    for (var i1=1;i1<N;i1++) up+=" L "+px(i1).toFixed(1)+","+py(k*sigs[i1]).toFixed(1);
    for (var i2=N-1;i2>=0;i2--) up+=" L "+px(i2).toFixed(1)+","+py(-k*sigs[i2]).toFixed(1);
    up+=" Z";
    g+='<path d="'+up+'" fill="rgba(22,112,106,0.16)" stroke="none"/>';
    // Contours de l'enveloppe
    var uo="M "+px(0).toFixed(1)+","+py(k*sigs[0]).toFixed(1);
    for (var i3=1;i3<N;i3++) uo+=" L "+px(i3).toFixed(1)+","+py(k*sigs[i3]).toFixed(1);
    g+='<path d="'+uo+'" fill="none" stroke="var(--teal)" stroke-width="1.8"/>';
    var lo="M "+px(0).toFixed(1)+","+py(-k*sigs[0]).toFixed(1);
    for (var i4=1;i4<N;i4++) lo+=" L "+px(i4).toFixed(1)+","+py(-k*sigs[i4]).toFixed(1);
    g+='<path d="'+lo+'" fill="none" stroke="var(--teal)" stroke-width="1.8"/>';
    // Ligne zéro
    g+='<line class="axis" x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'"/>';
    // Rendements (barres fines) + exceptions en rouge
    for (var t2=0;t2<N;t2++){
      var xx=px(t2), br=(Math.abs(rets[t2])>k*sigs[t2]);
      g+='<line x1="'+xx.toFixed(1)+'" y1="'+py(0).toFixed(1)+'" x2="'+xx.toFixed(1)+'" y2="'+py(rets[t2]).toFixed(1)+'" stroke="'+(br?'var(--crimson)':'var(--ink-mute)')+'" stroke-width="'+(br?'1.8':'1')+'" opacity="'+(br?'0.95':'0.55')+'"/>';
      if (br) g+='<circle cx="'+xx.toFixed(1)+'" cy="'+py(rets[t2]).toFixed(1)+'" r="2.4" fill="var(--crimson)"/>';
    }
    // Axe Y : ticks ±ymax
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">+'+(ymax*100).toFixed(0)+'%</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(0)+4).toFixed(1)+'" text-anchor="end">0</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(-ymax)+4).toFixed(1)+'" text-anchor="end">−'+(ymax*100).toFixed(0)+'%</text>';
    // Légende axe X
    var al=document.body.getAttribute("data-active-lang");
    var xlab = al==="en"?"time (trading days)":(al==="nl"?"tijd (beursdagen)":"temps (jours de bourse)");
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    svg.innerHTML=g;
  }

  ["vol-lam","vol-k"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
